    throw new Error(`Unknown tool: ${name}`);
  }
  if (args == null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const keys = Object.keys(args);
  const expected = ['a', 'b', 'operation'];
  if (keys.length !== 3 || !expected.every((k) => Object.prototype.hasOwnProperty.call(args, k))) {
    throw new Error('Missing or extra fields');
  }
  const { a, b, operation } = args;
  if (typeof a !== 'number' || !Number.isFinite(a) || typeof b !== 'number' || !Number.isFinite(b)) {
    throw new Error('a and b must be finite numbers');
  }
  switch (operation) {
    case 'add':
      return { content: [{ type: 'text', text: String(a + b) }] };
